@@ -150,4 +150,93 @@ class ReservationServiceTest {
     void anUnknownReservationIsNotFound() {
         assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
     }
+
+    private static NewReservation stayWithCompany(
+            int roomNumber, String checkIn, String checkOut, RatePlan plan, String companyCode) {
+        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
+        return new NewReservation(
+                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 2, plan, companyCode);
+    }
+
+    @Test
+    void corporatePlanDiscountsByCompanyAndRefundsEverything() {
+        Reservation reservation = service.create(
+                stayWithCompany(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL"));
+
+        assertEquals(new BigDecimal("779.80"), reservation.price().subtotal());
+        assertEquals(new BigDecimal("93.58"), reservation.price().discount());
+        assertEquals(new BigDecimal("686.22"), reservation.price().total());
+
+        service.confirm(reservation.id());
+        service.cancel(reservation.id());
+        assertEquals(new BigDecimal("686.22"), reservation.refund());
+    }
+
+    @Test
+    void corporatePlanNeedsAKnownCompanyCode() {
+        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
+                stayWithCompany(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, null))));
+        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
+                stayWithCompany(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "ACME"))));
+        assertEquals(new BigDecimal("0.25"), CorporateAgreement.forCode("FARMAVIDA").discount());
+        assertEquals(new BigDecimal("0.18"), CorporateAgreement.forCode("AGROVALE").discount());
+    }
+
+    @Test
+    void companyCodeIsIgnoredByOtherPlans() {
+        Reservation reservation = service.create(
+                stayWithCompany(101, "2027-03-10", "2027-03-11", RatePlan.STANDARD, "ACME"));
+
+        assertEquals(new BigDecimal("249.90"), reservation.price().total());
+    }
+
+    @Test
+    void weekendPackageHasAClosedPriceAndRefundsHalf() {
+        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
+
+        assertEquals(new BigDecimal("820.00"), reservation.price().subtotal());
+        assertEquals(new BigDecimal("0.00"), reservation.price().discount());
+        assertEquals(new BigDecimal("820.00"), reservation.price().total());
+
+        service.confirm(reservation.id());
+        service.cancel(reservation.id());
+        assertEquals(new BigDecimal("410.00"), reservation.refund());
+    }
+
+    @Test
+    void weekendPackageIsTheSamePriceInHighSeasonAndForOtherRooms() {
+        assertEquals(new BigDecimal("1200.00"),
+                service.create(stay(301, "2027-01-08", "2027-01-10", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
+        assertEquals(new BigDecimal("520.00"),
+                service.create(stay(101, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
+    }
+
+    @Test
+    void weekendPackageOnlyFromFridayToSunday() {
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+    }
+
+    @Test
+    void longStayTakes10PercentOffFromSevenNightsAndRefundsEverything() {
+        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
+
+        assertEquals(new BigDecimal("1749.30"), reservation.price().subtotal());
+        assertEquals(new BigDecimal("174.93"), reservation.price().discount());
+        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
+
+        service.confirm(reservation.id());
+        service.cancel(reservation.id());
+        assertEquals(new BigDecimal("1574.37"), reservation.refund());
+    }
+
+    @Test
+    void longStayNeedsSevenNights() {
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(101, "2027-03-01", "2027-03-07", 2, RatePlan.LONG_STAY))));
+    }
 }

